package com.example.tracking.messaging;import com.example.tracking.model.LifecycleEvent;import com.example.tracking.repository.LifecycleEventRepository;import org.springframework.kafka.annotation.KafkaListener;import org.springframework.stereotype.Component;@Component public class LifecycleEventConsumer{private final LifecycleEventRepository repository;public LifecycleEventConsumer(LifecycleEventRepository repository){this.repository=repository;}@KafkaListener(topics="order-lifecycle-events",groupId="tracking-service")public void consume(LifecycleEvent event){repository.save(event);}}
